import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"PlaceholderAPI Placeholders","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/storage/placeholders.md","filePath":"en/modules/storage/placeholders.md","lastUpdated":0}`),a={name:`en/modules/storage/placeholders.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="placeholderapi-placeholders" tabindex="-1">PlaceholderAPI Placeholders <a class="header-anchor" href="#placeholderapi-placeholders" aria-label="Permalink to “PlaceholderAPI Placeholders”">​</a></h1><p>The placeholders EmakiStorage registers with PlaceholderAPI, together with how they resolve, are listed below and ready to paste into scoreboards, menus and other text templates</p><p>Prerequisite: PlaceholderAPI is present. When it is, EmakiStorage registers the extension with identifier <code>emakistorage</code>. The placeholders work in scoreboards, menus, chat formats, boss bars, action bars and any other plugin text template that supports PlaceholderAPI</p><p>Without PlaceholderAPI, EmakiStorage itself still runs normally; it simply does not register the <code>%emakistorage_*%</code> external placeholders</p><h2 id="placeholder-list" tabindex="-1">Placeholder List <a class="header-anchor" href="#placeholder-list" aria-label="Permalink to “Placeholder List”">​</a></h2><table tabindex="0"><thead><tr><th>Placeholder</th><th>Description</th></tr></thead><tbody><tr><td><code>%emakistorage_used_slots%</code></td><td>Slots currently holding an entry</td></tr><tr><td><code>%emakistorage_total_slots%</code></td><td>Effective total slots</td></tr><tr><td><code>%emakistorage_free_slots%</code></td><td>Remaining free slots</td></tr><tr><td><code>%emakistorage_purchased_slots%</code></td><td>Purchased slots</td></tr><tr><td><code>%emakistorage_granted_slots%</code></td><td>Granted slots</td></tr><tr><td><code>%emakistorage_pages%</code></td><td>Total pages</td></tr><tr><td><code>%emakistorage_stack_limit%</code></td><td>The currently effective player-level per-slot ceiling</td></tr><tr><td><code>%emakistorage_sort_mode%</code></td><td>The current sort mode id</td></tr><tr><td><code>%emakistorage_total_amount%</code></td><td>Summed amount across every entry, saturating at <code>Long.MAX_VALUE</code></td></tr><tr><td><code>%emakistorage_count_&lt;token&gt;%</code></td><td>Stored amount for the given ItemSource token, <code>0</code> when absent</td></tr></tbody></table><h2 id="resolution-thread-and-unloaded-data" tabindex="-1">Resolution Thread and Unloaded Data <a class="header-anchor" href="#resolution-thread-and-unloaded-data" aria-label="Permalink to “Resolution Thread and Unloaded Data”">​</a></h2><p>Thread constraint: every placeholder reads the in-memory storage of an online player and never loads from disk; a placeholder resolves on whatever thread PAPI calls it from, so blocking IO is not an option. Error handling: an unloaded storage reports <code>0</code>, and an unrecognised placeholder returns an empty string</p><p>Matching rules: placeholder names are case-insensitive, lower-cased before evaluation, so <code>%emakistorage_USED_SLOTS%</code> is equivalent to the all-lowercase form. The <code>count_</code> prefix is matched before any other name and the rest is parsed as a CoreLib ItemSource token (also lower-cased first); an unparseable token returns <code>0</code>. Every result is returned as a decimal string, with no thousands separators</p><p>Error handling: when the player argument is absent (for example evaluated from the console or without a player context) the extension returns an empty string rather than <code>0</code></p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to “Related Pages”">​</a></h2><ul><li><a href="./capacity.html">Capacity</a>: the four-source capacity model behind <code>total_slots</code>, <code>purchased_slots</code> and friends</li><li><a href="./events.html">Event API</a>: the Bukkit events to use when you need to intercept rather than only read</li><li><a href="./api.html">API and Integration</a>: reading capacity and stored amounts from code</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};